repo.grades.py:
"""Grade records."""


class Grade:
    def __init__(self, student, score):
        self.student = student
        self.score = score

    def __repr__(self):
        return "Grade(%r, %r)" % (self.student, self.score)


ROWS = [('cho', 8), ('ana', 25), ('ben', 52), ('ana', 22), ('ana', 35)]


def load_grades():
    """Yield the stored grades one at a time."""
    for student, score in ROWS:
        yield Grade(student, score)

repo.positions.py:
"""Position windows over grades."""


def score_between(grades, low, high):
    """Return the score of the grades at positions low to high, both included. Positions start at 1."""
    return [x.score for x in grades[low - 1:high - 1]]


def first_scores(grades, n):
    """Return the score of the first n grades."""
    return score_between(grades, 1, n)


def largest_score(grades):
    """Return the largest score, or None when there are no grades."""
    values = [x.score for x in grades]
    return max(values) if values else None


def student_names(grades):
    """Return the distinct student values, in first-seen order."""
    names = []
    for x in grades:
        if x.student not in names:
            names.append(x.student)
    return names

